import {
    DataTexture,
    LinearFilter,
    LinearMipmapLinearFilter,
    RepeatWrapping,
    SRGBColorSpace,
} from "three";

import {
    PATTERN_SIZE,
    SURFACE_PATTERNS,
    grassPixels,
    tilesPixels,
    type PatternPixels,
} from "../utils/patternPixels";
import type { SurfaceMaterialId } from "../utils/surfaceMaterials";

/** A colour map and its relief, both generated by code: the project ships no image files. */
export interface Pattern {
    map: DataTexture;
    bump: DataTexture;
}

export interface Patterns {
    /** Surfaces that are drawn with a pattern instead of a flat colour. */
    surfaces: Partial<Record<SurfaceMaterialId, Pattern>>;
    roof: Pattern;
    grass: Pattern;
}

function finish(data: Uint8Array, tileM: number, color: boolean): DataTexture {
    const texture = new DataTexture(data, PATTERN_SIZE, PATTERN_SIZE);

    texture.wrapS = RepeatWrapping;
    texture.wrapT = RepeatWrapping;
    texture.repeat.setScalar(1 / tileM);
    texture.magFilter = LinearFilter;
    texture.minFilter = LinearMipmapLinearFilter;
    texture.generateMipmaps = true;
    texture.anisotropy = 4;

    if (color) {
        texture.colorSpace = SRGBColorSpace;
    }

    texture.needsUpdate = true;
    // The patterns outlive every model: releasing a model must not release them.
    texture.userData.shared = true;

    return texture;
}

function toPattern({ colors, heights, tileM }: PatternPixels): Pattern {
    return { map: finish(colors, tileM, true), bump: finish(heights, tileM, false) };
}

export function buildPatterns(roofColor: number, grassColor: number): Patterns {
    const surfaces: Partial<Record<SurfaceMaterialId, Pattern>> = {};

    for (const [id, make] of Object.entries(SURFACE_PATTERNS)) {
        surfaces[id as SurfaceMaterialId] = toPattern(make());
    }

    return {
        surfaces,
        roof: toPattern(tilesPixels(roofColor)),
        grass: toPattern(grassPixels(grassColor)),
    };
}

export function disposePatterns(patterns: Patterns): void {
    for (const pattern of [...Object.values(patterns.surfaces), patterns.roof, patterns.grass]) {
        pattern.map.dispose();
        pattern.bump.dispose();
    }
}
